-- Simplify 12 statuses to 5: Open, In review, On hold, Resolved, Closed. Existing data is mapped, nothing is lost.
-- 1. Allow old and new values together.
ALTER TABLE `feedback_submissions` MODIFY `status` ENUM('SUBMITTED','RECEIVED','UNDER_REVIEW','ASSIGNED','INVESTIGATION','ACTION_REQUIRED','RESOLVED','CLOSED','REJECTED','DUPLICATE','ESCALATED','AWAITING_INFO','OPEN','IN_REVIEW','ON_HOLD') NOT NULL DEFAULT 'SUBMITTED';
ALTER TABLE `feedback_status_history` MODIFY `fromStatus` ENUM('SUBMITTED','RECEIVED','UNDER_REVIEW','ASSIGNED','INVESTIGATION','ACTION_REQUIRED','RESOLVED','CLOSED','REJECTED','DUPLICATE','ESCALATED','AWAITING_INFO','OPEN','IN_REVIEW','ON_HOLD') NULL, MODIFY `toStatus` ENUM('SUBMITTED','RECEIVED','UNDER_REVIEW','ASSIGNED','INVESTIGATION','ACTION_REQUIRED','RESOLVED','CLOSED','REJECTED','DUPLICATE','ESCALATED','AWAITING_INFO','OPEN','IN_REVIEW','ON_HOLD') NOT NULL;

-- 2. Map old values to new ones.
UPDATE `feedback_submissions` SET `status` = CASE `status` WHEN 'SUBMITTED' THEN 'OPEN' WHEN 'RECEIVED' THEN 'OPEN' WHEN 'UNDER_REVIEW' THEN 'IN_REVIEW' WHEN 'ASSIGNED' THEN 'IN_REVIEW' WHEN 'INVESTIGATION' THEN 'IN_REVIEW' WHEN 'ACTION_REQUIRED' THEN 'IN_REVIEW' WHEN 'ESCALATED' THEN 'IN_REVIEW' WHEN 'AWAITING_INFO' THEN 'ON_HOLD' WHEN 'REJECTED' THEN 'CLOSED' WHEN 'DUPLICATE' THEN 'CLOSED' ELSE `status` END;
UPDATE `feedback_status_history` SET `toStatus` = CASE `toStatus` WHEN 'SUBMITTED' THEN 'OPEN' WHEN 'RECEIVED' THEN 'OPEN' WHEN 'UNDER_REVIEW' THEN 'IN_REVIEW' WHEN 'ASSIGNED' THEN 'IN_REVIEW' WHEN 'INVESTIGATION' THEN 'IN_REVIEW' WHEN 'ACTION_REQUIRED' THEN 'IN_REVIEW' WHEN 'ESCALATED' THEN 'IN_REVIEW' WHEN 'AWAITING_INFO' THEN 'ON_HOLD' WHEN 'REJECTED' THEN 'CLOSED' WHEN 'DUPLICATE' THEN 'CLOSED' ELSE `toStatus` END, `fromStatus` = CASE `fromStatus` WHEN 'SUBMITTED' THEN 'OPEN' WHEN 'RECEIVED' THEN 'OPEN' WHEN 'UNDER_REVIEW' THEN 'IN_REVIEW' WHEN 'ASSIGNED' THEN 'IN_REVIEW' WHEN 'INVESTIGATION' THEN 'IN_REVIEW' WHEN 'ACTION_REQUIRED' THEN 'IN_REVIEW' WHEN 'ESCALATED' THEN 'IN_REVIEW' WHEN 'AWAITING_INFO' THEN 'ON_HOLD' WHEN 'REJECTED' THEN 'CLOSED' WHEN 'DUPLICATE' THEN 'CLOSED' ELSE `fromStatus` END;

-- 3. Keep only the new values.
ALTER TABLE `feedback_submissions` MODIFY `status` ENUM('OPEN','IN_REVIEW','ON_HOLD','RESOLVED','CLOSED') NOT NULL DEFAULT 'OPEN';
ALTER TABLE `feedback_status_history` MODIFY `fromStatus` ENUM('OPEN','IN_REVIEW','ON_HOLD','RESOLVED','CLOSED') NULL, MODIFY `toStatus` ENUM('OPEN','IN_REVIEW','ON_HOLD','RESOLVED','CLOSED') NOT NULL;